    private int mode;

    /** The entry's user id. */
    private long userId = 0;

    /** The entry's group id. */
    private long groupId = 0;

    /** The entry's size. */
    private long size = 0;

    /** The entry's modification time. */
    private long modTime;

    /** If the header checksum is reasonably correct. */
    private boolean checkSumOK;

