        this(name, preserveLeadingSlashes);
        this.linkFlag = linkFlag;
        if (linkFlag == LF_GNUTYPE_LONGNAME) {
            magic = MAGIC_GNU;
            version = VERSION_GNU_SPACE;
        }
    }

public TarArchiveEntry(final File file) {
        this(file, file.getPath());
    }

